/**
 * @param x - array of datums
 * @param y - array of datums
 * @param propertyName - property of the datum that will compare
 * @returns - if both datums are equals
 */
export function areDatumsEqualBy<Datum>(
  x: Datum[],
  y: Datum[],
  propertyName: string,
): boolean {
  if (x.length !== y.length) {
    return false;
  }

  for (let index = 0; index < x.length; index++) {
    const xValue = x[index];
    const yValue = y[index];
    if (typeof xValue === typeof yValue) {
      if (typeof xValue === 'object') {
        const xPropertyValue = (xValue as Record<string, unknown>)[
          propertyName
        ];
        const yPropertyValue = (yValue as Record<string, unknown>)[
          propertyName
        ];

        if (xPropertyValue !== yPropertyValue) {
          return false;
        }
      }
    } else {
      return false;
    }
  }

  return true;
}
